// This file was generated by Prisma and assumes you have installed the
// following: npm install --save-dev prisma dotenv
import "dotenv/config";
import { defineConfig } from "prisma/config";

/**
 * Used by Migrate and introspection only — the runtime client connects through
 * the PrismaPg adapter in src/lib/prisma.ts instead. It must be DIRECT_URL
 * (session pooler, :5432): DDL over the transaction pooler on :6543 hangs
 * silently rather than erroring.
 *
 * Read through `process.env` rather than Prisma's `env()` helper, and the
 * datasource is omitted entirely when it is absent. `env()` THROWS on a
 * missing variable, and this config is loaded by every Prisma command —
 * including `prisma generate`, which needs no database at all. That turned a
 * deploy with no DIRECT_URL into "Cannot resolve environment variable" during
 * install, and left the generated client missing so the build failed on an
 * unresolvable import.
 *
 * Migrate still fails loudly if it is genuinely needed and missing; it just
 * fails at the point where a database connection is actually required.
 */

export default defineConfig({
  schema: "prisma/schema.prisma",
  migrations: {
    path: "prisma/migrations",
  },
  datasource: {
    // Use process.env instead of env("DIRECT_URL") so prisma generate doesn't crash
    url: process.env.DIRECT_URL ?? process.env.DATABASE_URL ?? "",
  },});
